INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein Flachbettscanner immer langsamer als ein Einzugsscanner ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Modell und Einstellung"}, {"text": "Ja", "correct": false, "because": "Nicht immer langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie wird typischerweise für Barcodescanner verwendet?', 3, '[{"text": "Laser", "correct": true, "because": "Präzise und schnell"}, {"text": "Infrarot", "correct": false, "because": "Weniger gebräuchlich"}, {"text": "Ultraschall", "correct": false, "because": "Nicht für Barcodes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für einen Dokumentenscanner wichtig?', 5, '[{"text": "Auflösung", "correct": true, "because": "Bestimmt Bildqualität"}, {"text": "Scangeschwindigkeit", "correct": true, "because": "Beeinflusst Effizienz"}, {"text": "Gerätegröße", "correct": false, "because": "Sekundär"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) OCR verbessert die Texterkennung. b) Es verdoppelt die Scangeschwindigkeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, OCR beeinflusst Geschwindigkeit nicht direkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Geräts zur Datenerfassung?', 4, '[{"text": "Konnektivität", "correct": false, "because": "Wichtig für Integration"}, {"text": "Auflösung", "correct": false, "because": "Bestimmt Qualität"}, {"text": "Gerätefarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Barcodescanner auch 2D-Codes lesen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Moderne Modelle lesen QR-Codes"}, {"text": "Nein", "correct": false, "because": "2D-Codes werden unterstützt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature verbessert die Effizienz bei Dokumentenscans?', 4, '[{"text": "Automatischer Einzug", "correct": true, "because": "Erlaubt Mehrfachscans"}, {"text": "Manuelle Kalibrierung", "correct": false, "because": "Verlangsamt Prozess"}, {"text": "Bildschirmgröße", "correct": false, "because": "Kein Scaneinfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass mobile Scanner langsamer sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Modell"}, {"text": "Ja", "correct": false, "because": "Moderne Geräte oft schnell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzen alle Scanner CCD-Sensoren?', 2, '[{"text": "Nein", "correct": true, "because": "Auch CIS-Sensoren üblich"}, {"text": "Ja", "correct": false, "because": "Nicht ausschließlich CCD"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schnittstellen sind für moderne Scanner typisch?', 5, '[{"text": "USB", "correct": true, "because": "Weit verbreitet"}, {"text": "Wi-Fi", "correct": true, "because": "Für kabellose Nutzung"}, {"text": "Parallelport", "correct": false, "because": "Veraltet"}, {"text": "VGA", "correct": false, "because": "Für Monitore"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Auswahl eines Geräts für ein Büro?', 4, '[{"text": "Hohe Scangeschwindigkeit", "correct": true, "because": "Steigert Produktivität"}, {"text": "Kleine Größe", "correct": false, "because": "Sekundär"}, {"text": "Bunte Oberfläche", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Einzugsscanner ist für Stapel geeignet. b) Er ist immer tragbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, oft stationär"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine effiziente Datenerfassung?', 3, '[{"text": "Hohe Auflösung", "correct": false, "because": "Verbessert Qualität"}, {"text": "OCR-Software", "correct": false, "because": "Erleichtert Texterkennung"}, {"text": "Farbiges Gehäuse", "correct": true, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich einen Scanner für Stapelverarbeitung wähle?', 4, '[{"text": "Einzugsscanner mit ADF prüfen", "correct": true, "because": "Automatisiert Mehrfachscans"}, {"text": "Flachbettscanner wählen", "correct": false, "because": "Langsamer für Stapel"}, {"text": "Handscanner kaufen", "correct": false, "because": "Ungeeignet für Stapel"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass alle Scanner USB benötigen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Wi-Fi oder Netzwerk möglich"}, {"text": "Ja", "correct": false, "because": "Andere Schnittstellen üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip verbessert die Texterkennung?', 4, '[{"text": "OCR-Integration", "correct": true, "because": "Wandelt Bilder in Text"}, {"text": "Höhere Farbtiefe", "correct": false, "because": "Sekundär für Text"}, {"text": "Manuelle Eingabe", "correct": false, "because": "Ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein 300-dpi-Scan immer ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderung"}, {"text": "Ja", "correct": false, "because": "Höhere Auflösung oft nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein mobiler Scanner?', 5, '[{"text": "Portabilität", "correct": true, "because": "Einsatz unterwegs"}, {"text": "Flexible Nutzung", "correct": true, "because": "Unabhängig von Büro"}, {"text": "Maximale Auflösung", "correct": false, "because": "Oft niedriger"}, {"text": "Hohe Scangeschwindigkeit", "correct": false, "because": "Eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Geräts unwichtig?', 3, '[{"text": "Auflösung", "correct": false, "because": "Bestimmt Qualität"}, {"text": "Konnektivität", "correct": false, "because": "Beeinflusst Integration"}, {"text": "Gewicht der Verpackung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Dokumente für Archivierung erfasse?', 4, '[{"text": "Hohe Auflösung und OCR nutzen", "correct": true, "because": "Sichert Qualität und Suche"}, {"text": "Niedrige Auflösung wählen", "correct": false, "because": "Schlechte Lesbarkeit"}, {"text": "Nur Farbscan machen", "correct": false, "because": "Sekundär"}]');
